// MMX — sim/lob_simulator.h
// Replay-driven backtester for MMX (spec §9).

#pragma once

#include <cstdint>
#include <functional>
#include <string>
#include <vector>

#include "host/ipc/param_block.h"
#include "host/math/ewma.h"
#include "host/math/kappa_fit.h"
#include "host/risk/pnl_tracker.h"
#include "host/threads/param_compiler.h"
#include "host/util/spsc_queue.h"
#include "queue_model.h"

namespace mmx {

// Compact L2 event used by the simulator. Generated by replay or by tests.
struct LobEvent {
    std::uint64_t ts_ns;
    int32_t       bid_ticks;     // best bid
    int32_t       ask_ticks;     // best ask
    uint32_t      bid_qty;       // total resting volume at best bid
    uint32_t      ask_qty;       // ask side resting volume
    int8_t        trade_side;    // +1 = buy aggressor crossed ask, -1 = sell aggressor crossed bid, 0 = no trade
    uint32_t      trade_qty;     // 0 if not a trade
    int32_t       trade_price;   // ticks
};

struct SimParams {
    double        tick_size       = 1.0;
    int32_t       maker_fee_ticks = -1;     // negative = rebate
    std::uint64_t toxic_window_ns = 5'000'000'000ULL;  // 5 s
    int32_t       toxic_threshold_ticks = 1;

    // Strategy knobs (mirror ParamCompilerInputs).
    double        gamma           = 0.1;
    double        horizon_sec     = 600.0;
    uint32_t      max_inv         = 100;
    uint32_t      base_qty        = 1;
    uint16_t      requote_ticks   = 1;

    // EWMA sample interval (ns) — recompute σ², κ, ParamBlock at this cadence.
    std::uint64_t refresh_period_ns = 100'000'000ULL;  // 100 ms

    // --- Order-Flow-Imbalance (OFI) defence against adverse selection ---
    // A causal slow-path signal computed only from PAST trades: the EWMA of
    // signed aggressor volume. Two effects, applied on top of the (untouched)
    // FPGA pricing kernel via the quote overlay:
    //   ofi_skew_k  — shift both quotes in the direction of recent flow, so the
    //                 maker stops selling into a rally / buying into a sell-off
    //                 (and leans WITH the flow). 0 = off.
    //   ofi_widen_k — widen the half-spread in proportion to |OFI|, pulling the
    //                 vulnerable side back when flow turns toxic. 0 = off.
    //   ofi_lambda  — EWMA decay for the imbalance estimate.
    //
    // Validated default (sim/cv_harness.cpp, CTest `test_mmx_no_overfit`): a
    // POSITIVE ofi_widen_k is the robust, out-of-sample defence against the
    // adverse selection caused by quote latency, whereas ofi_skew_k (a
    // directional bet on flow) gives no generalising edge across disjoint
    // train/test seeds. Keep ofi_skew_k at 0 unless a genuine predictive signal
    // justifies a directional lean — this is what keeps the strategy from
    // overfitting a single price path.
    double ofi_skew_k  = 0.0;
    double ofi_widen_k = 0.0;
    double ofi_lambda  = 0.90;
    int32_t ofi_max_skew_ticks = 12;   // clamp so the overlay can't run away

    // Quote staleness: the maker prices off a mid that is this many events old,
    // modelling its reaction latency. With δ>0 the maker posts stale quotes
    // that informed flow can pick off before they are refreshed — i.e. real
    // adverse selection. δ=0 is the (unrealistic) zero-latency idealization.
    // The whole point of the FPGA fast path is to drive δ toward zero.
    int quote_latency_events = 0;
};

struct SimResult {
    double  pnl_total         = 0.0;
    double  sharpe            = 0.0;
    double  sortino           = 0.0;
    double  max_drawdown      = 0.0;
    int     fills             = 0;
    int     fills_bid         = 0;
    int     fills_ask         = 0;
    double  fill_rate_bid     = 0.0;
    double  fill_rate_ask     = 0.0;
    double  inventory_l1_norm = 0.0;
    double  avg_quote_age_ms  = 0.0;
    double  toxic_fill_share  = 0.0;
};

class LobSimulator {
  public:
    explicit LobSimulator(SimParams params,
                          std::vector<std::uint8_t> hmac_key);

    void load_events(std::vector<LobEvent> events) {
        events_ = std::move(events);
    }

    SimResult run();

    // End-of-day inventory flattening: realise any open inventory at the given
    // mid and reset resting quotes, so the next session starts flat. Standard
    // market-maker practice — a desk does not carry microstructure inventory
    // overnight. Flattening at mid converts unrealised P&L to realised without
    // changing total P&L; its only effect is to free the inventory cap for the
    // next day.
    void flatten_inventory(int32_t mid_ticks);

    // Current signed inventory (lots) and cumulative P&L marked at `mid_ticks`.
    int32_t inventory() const;
    double  cumulative_pnl(int32_t mid_ticks) const;

    // Inspect last produced ParamBlock (for tests / debugging).
    const ParamBlock& last_param_block() const { return last_block_; }

  private:
    SimParams                 params_;
    std::vector<std::uint8_t> hmac_key_;
    ParamCompiler             compiler_;
    EwmaVariance              ewma_;
    KappaEstimator            kappa_;
    PnlTracker                pnl_;
    QueueModel                bid_q_;
    QueueModel                ask_q_;
    ParamBlock                last_block_{};

    std::vector<LobEvent>     events_;
};

}  // namespace mmx
